import{_ as e,a,c as t,b as n}from"./chunks/framework.b9WMfGr4.js";const u=JSON.parse('{"title":"04-归档与标签统计组件","description":"深入解析博文归档 ArchiveList、标签统计 TagStats 与最新文章 RecentPosts 组件的演进与数据流设计。","frontmatter":{"title":"04-归档与标签统计组件","date":"2026-10-01T00:00:00.000Z","author":"道林学长","description":"深入解析博文归档 ArchiveList、标签统计 TagStats 与最新文章 RecentPosts 组件的演进与数据流设计。","tags":["组件设计","归档列表"]},"headers":[],"relativePath":"posts/0-博客指南/博客的组件设计/04-归档与标签统计组件.md","filePath":"posts/0-博客指南/博客的组件设计/04-归档与标签统计组件.md"}'),o={name:"posts/0-博客指南/博客的组件设计/04-归档与标签统计组件.md"};function i(r,s,l,p,c,d){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 class="hidden-duplicate-h1" style="display:none !important;" id="_04-归档与标签统计组件" tabindex="-1">04-归档与标签统计组件 <a class="header-anchor" href="#_04-归档与标签统计组件" aria-label="Permalink to &quot;04-归档与标签统计组件&quot;">​</a></h1><div class="post-cover-wrapper"><img src="https://images.unsplash.com/photo-1434030216411-0b793f4b4173?auto=format&amp;fit=crop&amp;w=1200&amp;q=80" alt="cover" class="post-cover-image" referrerpolicy="no-referrer" loading="lazy"></div><p>在博文总览页与首页边栏，如何高效汇聚零散的文章元数据并以整洁的时间线与标签谱系展现，是博客归档体系设计的核心关注点。</p><h2 id="_1-经典时间线归档组件-archivelist" tabindex="-1">1. 经典时间线归档组件 ArchiveList <a class="header-anchor" href="#_1-经典时间线归档组件-archivelist" aria-label="Permalink to &quot;1. 经典时间线归档组件 ArchiveList&quot;">​</a></h2><p>归档列表组件 <code>ArchiveList.vue</code> 部署于全站博文页面，用于展示所有公开发布的技术文章：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>2026 (大号等宽字体年份标识)</span></span>
<span class="line"><span>  ├── 10-01  文章标题 A ───────────────────── 5 分钟</span></span>
<span class="line"><span>  ├── 09-30  文章标题 B ───────────────────── 3 分钟</span></span>
<span class="line"><span>  └── 08-19  文章标题 C ───────────────────── 8 分钟</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><ul><li><strong>年份分组聚类</strong>：组件自动提取每篇文章发布日期的年份属性，按时间倒序分组组织，形成清晰的历史沉淀脉络。</li><li><strong>等宽紧凑排版</strong>：日期采用 <code>MM-DD</code> 格式的等宽字体呈现，标题占据弹性主干区域，悬浮时平滑呈现透明度过渡。</li><li><strong>阅读时长精准测算</strong>：系统根据正文有效字数除以标准阅读速率，动态推导出预估阅读时长并在行尾标注，帮助读者合理规划碎片化阅读时间。</li></ul><h2 id="_2-标签聚合与双阈值过滤算法-tagstats" tabindex="-1">2. 标签聚合与双阈值过滤算法 TagStats <a class="header-anchor" href="#_2-标签聚合与双阈值过滤算法-tagstats" aria-label="Permalink to &quot;2. 标签聚合与双阈值过滤算法 TagStats&quot;">​</a></h2><p>标签作为正交于目录分类的网状索引，若缺乏合理的展示门槛，极易随博主行文产生大量仅使用一次的碎片化临时标签，进而将侧边栏塞满：</p><ul><li><strong>双阈值筛选策略</strong>：侧栏“文档标签”组件设定了双重过滤门槛，仅渲染全站使用频次不低于两次、且在全站标签总频次中占比不低于百分之五的核心标签。</li><li><strong>聚焦核心知识领域</strong>：过滤策略有效屏蔽了偶发性的微小标签，使得侧边栏展现出来的标签云高度代表博主的核心专业技术栈与长期深耕领域。</li><li><strong>全量检索能力保留</strong>：低频标签虽然不会主动占用侧边栏宝贵的可视空间，但在顶部全局搜索中依然保持全量索引，保证任意特定标签均可被精准检索定位。</li></ul><h2 id="_3-最新发布卡片-recentposts" tabindex="-1">3. 最新发布卡片 RecentPosts <a class="header-anchor" href="#_3-最新发布卡片-recentposts" aria-label="Permalink to &quot;3. 最新发布卡片 RecentPosts&quot;">​</a></h2><p>用于在博客首页关键视口展示近期最新撰写的博文：</p><ul><li><strong>按时间戳降序截取</strong>：数据加载器自动根据文章 Frontmatter 声明的日期或 Git 提交时间进行数值排序，截取前若干篇最新成果。</li><li><strong>精简摘要展示</strong>：卡片式罗列标题、分类标签与一句话导读摘要，便于常访读者快速捕捉最新技术动态。</li></ul>`,13)])])}const _=e(o,[["render",i]]);export{u as __pageData,_ as default};
